import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 34 Adolescence","description":"学习 倾向表达与概率范围，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 34 Adolescence","description":"学习 倾向表达与概率范围，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 倾向表达与概率范围，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 33 Education","link":"/life/english/new-concept/book-4/unit-05/lesson-033"},"next":{"text":"第四册：流利英语 · Lesson 35 Space odyssey","link":"/life/english/new-concept/book-4/unit-05/lesson-035"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 33 Education","link":"/life/english/new-concept/book-4/unit-05/lesson-033"},"next":{"text":"第四册：流利英语 · Lesson 35 Space odyssey","link":"/life/english/new-concept/book-4/unit-05/lesson-035"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-05/lesson-034.md","filePath":"life/english/new-concept/book-4/unit-05/lesson-034.md"}'),i={name:"life/english/new-concept/book-4/unit-05/lesson-034.md"};function l(s,e,r,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-34-adolescence" tabindex="-1">第四册：流利英语 · Lesson 34 Adolescence <a class="header-anchor" href="#第四册-流利英语-·-lesson-34-adolescence" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 34 Adolescence&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元 5</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>通过青春期主题训练对群体描述保持谨慎：个体发展速度、家庭背景与社会环境各不相同。学习表达倾向和可能性而非绝对规则，并把观察到的行为与对动机的猜测分开。重点掌握 tend to、be likely to 等结构，为观点设定合理强度。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>adolescence</td><td>/ˌædəˈlesəns/</td><td>n.</td><td>青春期</td><td>during adolescence</td></tr><tr><td>independence</td><td>/ˌɪndɪˈpendəns/</td><td>n.</td><td>独立</td><td>greater independence</td></tr><tr><td>peer</td><td>/pɪə/</td><td>n.</td><td>同龄人</td><td>peer support</td></tr><tr><td>identity</td><td>/aɪˈdentəti/</td><td>n.</td><td>身份认同</td><td>a sense of identity</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>tend to — 往往会，表示倾向</li><li>be likely to — 很可能会，仍保留例外</li></ul><h2 id="语法讲解-倾向表达与概率范围" tabindex="-1">语法讲解：倾向表达与概率范围 <a class="header-anchor" href="#语法讲解-倾向表达与概率范围" aria-label="Permalink to &quot;语法讲解：倾向表达与概率范围&quot;">​</a></h2><p>tend to do 描述常见倾向，不表示每次或所有人都如此；be likely to do 表示某情况发生的可能性较大，但不是必然。may 与 might 也能降低确定程度。Young people tend to seek… 仍是群体概括，应说明语境或证据来源。避免 tend to always 这类常常相互抵触的范围搭配；若只观察到某个学生，应保留单数对象而不要扩展成整个年龄群体。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>In this club, new members tend to ask their peers for help before approaching an adult.</p></blockquote><p>在这个俱乐部里，新成员往往先向同伴求助，再找成年人。</p><p>In this club 限定范围；tend to ask 表倾向；before approaching 与主语 new members 共享执行者。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>tend to 不等于 always；不能将示例改写成“所有青少年都只向同伴求助”。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>重读 In this club 与 tend，弱读 to；请听者复述适用范围，检查朗读是否把限定信息吞掉。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>In our discussion group, quieter members tend to speak after a friend has contributed. They may feel more confident with familiar support. Offering time to prepare could help everyone participate.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句关于一个青年活动组的观察，包含范围限制、可能原因和支持方式。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>限定具体群体，用 may 区分推测原因，再给出温和可执行的建议。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例的范围是所有青少年还是这个俱乐部的新成员？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 这个俱乐部的新成员。</p><p><strong>解析：</strong> 地点与主语共同限定了范围。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：She is likely ___ join the discussion.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> be likely to 后接动词原形。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用 tend to 改写“这些成员常先询问朋友”。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> These members tend to ask their friends first.</p><p><strong>解析：</strong> tend to 表通常倾向，不是必然。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：倾向表达与概率范围。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-033">上一课</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-05/lesson-035">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",l]]);export{u as __pageData,b as default};
